import React, { useEffect, useState, useCallback } from "react";

/**
 Props:
  - articleId: number
  - token: string (JWT)
  - currentUserId: number | null
  - isAdmin: boolean
*/
function CommentsSection({ articleId, token, currentUserId, isAdmin }) {
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState("");
  const [loading, setLoading] = useState(true);

  const fetchComments = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/comments/?article=${articleId}`
      );
      const data = await res.json();
      console.log("🔍 COMMENTS DATA:", data);
      setComments(data);
    } catch (err) {
      console.error("Помилка при завантаженні коментарів:", err);
    } finally {
      setLoading(false);
    }
  }, [articleId]);

  useEffect(() => {
    fetchComments();
  }, [fetchComments]);

  const handleAddComment = async () => {
    if (!newComment.trim()) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/comments/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: token ? `Bearer ${token}` : "",
        },
        body: JSON.stringify({ article: articleId, content: newComment }),
      });
      if (res.ok) {
        setNewComment("");
        fetchComments();
      } else {
        const err = await res.json().catch(() => null);
        console.error("Помилка при додаванні коментаря", err);
      }
    } catch (err) {
      console.error("Помилка при додаванні коментаря:", err);
    }
  };

  const handleDeleteComment = async (commentId) => {
    if (!window.confirm("Видалити коментар?")) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/comments/${commentId}/`, {
        method: "DELETE",
        headers: {
          Authorization: token ? `Bearer ${token}` : "",
        },
      });
      if (res.ok) {
        setComments((prev) => prev.filter((c) => c.id !== commentId));
      } else {
        const err = await res.json().catch(() => null);
        console.error("Помилка при видаленні коментаря", err);
      }
    } catch (err) {
      console.error("Помилка при видаленні коментаря:", err);
    }
  };

  // canDelete: true якщо currentUserId === author або якщо isAdmin === true
  const canDelete = (commentUser) => {
    if (isAdmin) return true;

    // commentUser може бути або number (id) або об'єкт { id, username, ... }
    if (commentUser == null) return false;
    if (typeof commentUser === "object") {
      return commentUser.id === currentUserId;
    }
    // якщо number або string
    return commentUser === currentUserId;
  };

  return (
    <div className="comments-section">
      <h4>Коментарі</h4>

      {loading ? (
        <p>Завантаження...</p>
      ) : comments.length > 0 ? (
        comments.map((c) => (
          <div key={c.id} className="comment">
            <div className="comment-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>{c.user_username || c.user?.username || `User ${c.user ?? ""}`}</strong>
                <div style={{ fontSize: "0.85em", color: "#666" }}>{new Date(c.created_at).toLocaleString()}</div>
              </div>

              {/* кнопка видалити з'являється тільки якщо canDelete === true */}
              {canDelete(c.user) ? (
                <button
                  className="delete-comment-btn"
                  onClick={() => handleDeleteComment(c.id)}
                  style={{ marginLeft: "12px" }}
                >
                  🗑️
                </button>
              ) : null}
            </div>

            <p style={{ whiteSpace: "pre-wrap", marginTop: "8px" }}>{c.content}</p>
          </div>
        ))
      ) : (
        <p>Немає коментарів.</p>
      )}

      {token ? (
        <div className="add-comment" style={{ marginTop: "12px" }}>
          <textarea
            placeholder="Напишіть коментар..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            style={{ width: "100%", minHeight: "60px" }}
          />
          <button onClick={handleAddComment} style={{ marginTop: "8px" }}>Надіслати</button>
        </div>
      ) : (
        <p>🔒 Увійдіть, щоб залишати коментарі</p>
      )}
    </div>
  );
}

export default CommentsSection;
